{
  "name": "@lucid-agents/opencode-x402-plugin",
  "version": "0.1.12",
  "description": "OpenCode auth plugin for x402 payment protocol - sign permits with your wallet",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    }
  },
  "sideEffects": false,
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc",
    "dev": "tsc --watch",
    "test": "vitest run",
    "test:watch": "vitest",
    "prepublishOnly": "npm run build"
  },
  "keywords": [
    "opencode",
    "x402",
    "auth",
    "plugin",
    "wallet",
    "crypto",
    "permit",
    "eip-712",
    "erc-2612"
  ],
  "author": "Daydreams AI",
  "license": "MIT",
  "dependencies": {
    "viem": "^2.44.4"
  },
  "devDependencies": {
    "@types/node": "^25.0.10",
    "msw": "2",
    "typescript": "^5.9.3",
    "vitest": "^2.1.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "*"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": {
      "optional": true
    }
  },
  "engines": {
    "node": ">=18.0.0"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/daydreamsai/router.git",
    "directory": "packages/opencode-x402-auth"
  },
  "bugs": {
    "url": "https://github.com/daydreamsai/router/issues"
  },
  "homepage": "https://github.com/daydreamsai/router/tree/master/packages/opencode-x402-auth",
  "publishConfig": {
    "access": "public"
  }
}
